  grammar: [
    {"pat": "V／イA／ナA／N thể thường ＋ んですが、～", "desc": "Dùng để mở đầu câu chuyện: nêu hoàn cảnh, lý do của mình trước, rồi nhờ vả, hỏi thông tin hay xin lời khuyên một cách lịch sự, mềm mỏng.\nVế sau thường là: ～てもらえませんか／～ていただけませんか／～てください／～を知りませんか／～たらいいですか.\n• V: 行きたい → 行きたいんですが\n• イA: 痛い → 痛いんですが\n• ナA: 静かだ → 静かなんですが\n• N: 休みだ → 休みなんですが\nLưu ý: ナA và N đổi だ → な trước ん. Trong hội thoại có thể chỉ nói vế trước rồi dừng (～たいんですが…) để đối phương tự hiểu.", "ex": [{"jp": "みどり公園（こうえん）へ行（い）きたいんですが、行（い）き方（かた）を教（おし）えてもらえませんか。", "ro": "Midori kouen e ikitai n desu ga, ikikata o oshiete moraemasen ka.", "vi": "Tôi muốn đến công viên Midori, anh/chị chỉ đường giúp tôi được không ạ?"}]},
    {"pat": "V thể thường／イA／ナA／N ＋ なら、～", "desc": "Nhận lấy chủ đề hoặc dự định mà đối phương vừa nói, rồi đưa ra lời khuyên, gợi ý, thông tin: “nếu là ~ thì…”, “nếu (định) ~ thì…”.\n• N → Nなら: 自転車 → 自転車なら\n• V → V thể thường ＋ なら: 切る → 切るなら\n• イA → イAなら: 安い → 安いなら\n• ナA → ナAなら (bỏ だ): 静かだ → 静かなら\nLưu ý: Với Vなら, việc ở vế sau (mua ở đâu, đi tiệm nào…) thường xảy ra trước hoặc để chuẩn bị cho việc ở vế trước; khác với Vたら (làm xong vế trước rồi mới đến vế sau).", "ex": [{"jp": "自転車（じてんしゃ）を買（か）いたいんですが、いい店（みせ）を知（し）りませんか。—自転車（じてんしゃ）なら、田中自転車（たなかじてんしゃ）がいいですよ。", "ro": "Jitensha o kaitai n desu ga, ii mise o shirimasen ka. — Jitensha nara, Tanaka Jitensha ga ii desu yo.", "vi": "Tôi muốn mua xe đạp, anh/chị có biết cửa hàng nào tốt không? — Xe đạp thì tiệm Tanaka Jitensha được đấy."}, {"jp": "髪（かみ）を切（き）りたいんですが、いい美容院（びよういん）を教（おし）えてください。—髪（かみ）を切（き）るなら、アンジェという美容院（びよういん）がいいです。", "ro": "Kami o kiritai n desu ga, ii biyouin o oshiete kudasai. — Kami o kiru nara, Anje to iu biyouin ga ii desu.", "vi": "Tôi muốn cắt tóc, chỉ giúp tôi một tiệm làm tóc tốt với. — Nếu cắt tóc thì tiệm tên là Ange được đấy."}]},
    {"pat": "V thể た ＋ らいいですか（Vたらいいですか）", "desc": "Hỏi xin lời khuyên, chỉ dẫn: “nên làm ~ thì được?”, “làm thế nào thì được?”. Thường đi với từ để hỏi どう／どこ／何／何番／だれ….\n• 乗る → 乗った → 乗ったらいいですか\n• 行く → 行った → 行ったらいいですか\n• する → した → したらいいですか\nCách trả lời: Vたらいいです／Vるといいです.", "ex": [{"jp": "何番（なんばん）のバスに乗（の）ったらいいですか。", "ro": "Nanban no basu ni nottara ii desu ka.", "vi": "Tôi nên đi xe buýt số mấy ạ?"}]},
    {"pat": "V thể từ điển ＋ といいです（Vるといいです）", "desc": "Đưa ra lời khuyên, gợi ý nhẹ nhàng: “làm ~ thì tốt đấy”, “nên làm ~”. Thường dùng để trả lời câu hỏi Vたらいいですか, hay đi cùng ～なら.\n• 買う → 買うといいです\n• 利用する → 利用するといいです\nLưu ý: dùng V thể từ điển (không dùng thể た) trước と.", "ex": [{"jp": "パソコンを買（か）うなら、サカイ電器（でんき）で買（か）うといいです。", "ro": "Pasokon o kau nara, Sakai Denki de kau to ii desu.", "vi": "Nếu mua máy tính thì nên mua ở cửa hàng điện máy Sakai."}]},
    {"pat": "N ＋ までに～", "desc": "Chỉ hạn chót: hành động phải hoàn thành trước hoặc muộn nhất là vào thời điểm N: “trước ~, chậm nhất là ~”. Vế sau là hành động xảy ra một lần (出す、申し込む、返す、帰る…).\nPhân biệt:\n• Nまで → hành động kéo dài liên tục đến N: 5時まで働きます (làm việc đến 5 giờ)\n• Nまでに → hành động xong trước N: 5時までに帰ります (về trước 5 giờ)", "ex": [{"jp": "スキー旅行（りょこう）に行（い）きたい人（ひと）は、明日（あした）までに申（もう）し込（こ）んでください。", "ro": "Sukii ryokou ni ikitai hito wa, ashita made ni moushikonde kudasai.", "vi": "Ai muốn tham gia chuyến đi trượt tuyết thì hãy đăng ký trước ngày mai."}]},
    {"pat": "V thể từ điển ＋ と、N があります", "desc": "Dùng khi chỉ đường: “làm V (đi, rẽ, qua…) thì sẽ thấy có N”. Vế sau là kết quả tất yếu, điều sẽ thấy được.\n• 曲がる → 曲がると、～があります\n• 行く → まっすぐ行くと、～があります\nLưu ý: vế sau と không dùng câu ý chí, mệnh lệnh, nhờ vả (～てください、～ましょう…).", "ex": [{"jp": "信号（しんごう）を右（みぎ）に曲（ま）がってまっすぐ行（い）くと、公園（こうえん）があります。", "ro": "Shingou o migi ni magatte massugu iku to, kouen ga arimasu.", "vi": "Rẽ phải ở chỗ đèn giao thông rồi đi thẳng là sẽ thấy công viên."}]},
    {"pat": "N／V thể từ điển ん ＋ じゃなくて、～", "desc": "Phủ định thông tin sai (thường là điều đối phương vừa nói hoặc hiểu nhầm) rồi đưa ra thông tin đúng: “không phải ~ mà là…”.\n• N → Nじゃなくて: 西口 → 西口じゃなくて\n• V → V thể từ điển ＋ んじゃなくて: 曲がる → 曲がるんじゃなくて\nLưu ý: với động từ phải có ん (曲がるじゃなくて là sai). Cách nói trang trọng: ～ではなくて.", "ex": [{"jp": "西口（にしぐち）じゃなくて、南口（みなみぐち）へ来（き）てください。", "ro": "Nishiguchi ja nakute, minamiguchi e kite kudasai.", "vi": "Không phải cửa Tây đâu, hãy đến cửa Nam nhé."}, {"jp": "2つ目（ふたつめ）の信号（しんごう）を右（みぎ）に曲（ま）がるんですね。—いいえ、曲（ま）がるんじゃなくて、まっすぐ行（い）ってください。", "ro": "Futatsume no shingou o migi ni magaru n desu ne. — Iie, magaru n ja nakute, massugu itte kudasai.", "vi": "Rẽ phải ở đèn giao thông thứ hai phải không ạ? — Không, không rẽ đâu, anh/chị cứ đi thẳng nhé."}]},
    {"pat": "Tóm tắt", "desc": "• Thể thường ＋ んですが、～ → nêu hoàn cảnh để nhờ vả, hỏi lịch sự\n• ～なら、～ → nếu là ~ thì… (gợi ý theo chủ đề đối phương nói)\n• Vたらいいですか → nên làm ~ thì được?\n• Vるといいです → làm ~ thì tốt đấy (khuyên)\n• Nまでに → trước ~, hạn chót ~ (khác Nまで: kéo dài đến ~)\n• Vると、Nがあります → làm ~ thì sẽ thấy N (chỉ đường)\n• Nじゃなくて／Vるんじゃなくて → không phải ~ mà là…", "ex": []}
  ],

